class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        def find_boundary(is_left: bool):
            left, right = 0, len(nums) - 1
            pos = -1 # 精华
            while left <= right:
                mid = (left + right) // 2
                if nums[mid] == target:
                    pos = mid # 精华
                    if is_left:
                        right = mid - 1
                    else:
                        left = mid + 1
                elif nums[mid] < target:
                    left = mid + 1
                else:
                    right = mid - 1
            return pos
        return [find_boundary(True), find_boundary(False)]
